package ec.edu.monster.servicio;
import ec.edu.monster.modelo.Resultado; import ec.edu.monster.persistencia.ConexionBD; import java.sql.*;
public class AdminService { public Resultado cliente(String p,String m,String n,String dni,String ci,String d,String t,String e){if(p==null||p.isBlank()||n==null||n.isBlank()||dni==null||dni.isBlank())return Resultado.error("Apellido paterno, nombre y DNI son obligatorios.");try(Connection c=ConexionBD.conectar();Statement st=c.createStatement();ResultSet r=st.executeQuery("SELECT LPAD(COALESCE(MAX(CAST(chr_cliecodigo AS UNSIGNED)),0)+1,5,'0') FROM cliente")){r.next();String x=r.getString(1);try(PreparedStatement q=c.prepareStatement("INSERT INTO cliente(chr_cliecodigo,vch_cliepaterno,vch_cliematerno,vch_clienombre,chr_cliedni,vch_clieciudad,vch_cliedireccion,vch_clietelefono,vch_clieemail) VALUES(?,?,?,?,?,?,?,?,?)")){String[] v={x,p,m,n,dni,ci,d,t,e};for(int i=0;i<v.length;i++)q.setString(i+1,v[i]==null?"":v[i]);q.executeUpdate();return Resultado.ok("Cliente registrado con código "+x+".",0);}}catch(SQLException z){return Resultado.error("No se pudo registrar el cliente: "+z.getMessage());}} public Resultado cuenta(String cl,String mon){if(cl==null||cl.isBlank())return Resultado.error("Código de cliente requerido.");if(mon==null||mon.isBlank())mon="02";if(!mon.equals("01")&&!mon.equals("02"))return Resultado.error("Moneda inválida (use 01 Soles o 02 Dólares).");try(Connection c=ConexionBD.conectar();PreparedStatement ex=c.prepareStatement("SELECT 1 FROM cliente WHERE chr_cliecodigo=?")){ex.setString(1,cl);try(ResultSet e=ex.executeQuery()){if(!e.next())return Resultado.error("El cliente "+cl+" no existe.");}try(Statement st=c.createStatement();ResultSet r=st.executeQuery("SELECT LPAD(COALESCE(MAX(CAST(chr_cuencodigo AS UNSIGNED)),0)+1,8,'0') FROM cuenta")){r.next();String x=r.getString(1);try(PreparedStatement q=c.prepareStatement("INSERT INTO cuenta(chr_cuencodigo,chr_monecodigo,chr_sucucodigo,chr_emplcreacuenta,chr_cliecodigo,dec_cuensaldo,dtt_cuenfechacreacion,vch_cuenestado,int_cuencontmov,chr_cuenclave) VALUES(?,?,'001','0001',?,0,CURDATE(),'ACTIVO',0,'123456')")){q.setString(1,x);q.setString(2,mon);q.setString(3,cl);q.executeUpdate();return Resultado.ok("Cuenta "+x+" creada para el cliente "+cl+".",0);}}}catch(SQLException z){return Resultado.error("No se pudo registrar la cuenta: "+z.getMessage());}} public Resultado eliminar(String n){if("00900000".equals(n))return Resultado.error("La cuenta MASTER del banco no se puede eliminar.");try(Connection c=ConexionBD.conectar()){c.setAutoCommit(false);try(PreparedStatement a=c.prepareStatement("DELETE FROM movimiento WHERE chr_cuencodigo=?");PreparedStatement b=c.prepareStatement("DELETE FROM cuenta WHERE chr_cuencodigo=?")){a.setString(1,n);a.executeUpdate();b.setString(1,n);int x=b.executeUpdate();c.commit();return x==0?Resultado.error("La cuenta "+n+" no existe."):Resultado.ok("Cuenta "+n+" eliminada (junto con sus movimientos).",0);}}catch(SQLException z){return Resultado.error("No se pudo eliminar la cuenta: "+z.getMessage());}} }
